type CacheContainerResource = Awaited<ReturnType<DistributedApplicationBuilder['addContainer']>>;
type CacheResource = AspireResource | CacheContainerResource;

/** Infrastructure context carrying database and cache resources for downstream registration. */
export interface InfrastructureContext {
  readonly databases: Map<string, AspireResource>;
  readonly databaseConnectionStrings: Map<string, DatabaseConnectionStringResolver>;
  readonly caches: Map<string, CacheResource>;
  readonly cacheEndpoints: Map<string, EndpointReference>;
  readonly cacheWiring: Map<string, CacheWiring>;
  readonly primaryDatabase: AspireResource | null;
  readonly primaryCache: CacheResource | null;
  readonly primaryCacheEndpoint: EndpointReference | null;
