/**
 * Registers databases and caches with the Aspire SDK builder.
 * Resolves primary database and primary cache from config.
 *
 * @param builder - The Aspire distributed application builder
 * @param config - Parsed NetScript configuration
 * @param appHostDir - Absolute path to the AppHost directory
 * @returns Infrastructure context with resource maps and primary references
 */
export async function registerInfrastructure(
  builder: DistributedApplicationBuilder,
  _config: NetScriptConfig,
  appHostDir: string,
): Promise<InfrastructureContext> {
  const databases = new Map<string, AspireResource>();
  const databaseConnectionStrings = new Map<string, DatabaseConnectionStringResolver>();
  const caches = new Map<string, CacheResource>();
  const cacheEndpoints = new Map<string, EndpointReference>();
  const cacheWiring = new Map<string, CacheWiring>();
