private async waitForDatabase(
  configKey: string,
  apphostPath: string,
  aspireDir: string,
  signal: AbortSignal,
): Promise<void> {
  const timeoutSeconds = Math.max(1, Math.ceil(this.timeoutMs / 1_000));
  const output = await this.executor.output(
    [
      'wait',
      configKey,
      '--status',
      'healthy',
      '--timeout',
      String(timeoutSeconds),
      '--apphost',
      apphostPath,
      '--non-interactive',
      '--nologo',
    ],
    { cwd: aspireDir, signal },
  );
  if (output.code === 0) return;

