  const args = [
    'resource',
    `${configKey}-cli`,
    operation,
    '--timeout',
    String(timeoutSeconds),
  ];
  if (operation === 'reset') args.push('--confirm', 'true');
  args.push('--apphost', apphostPath, '--non-interactive', '--nologo');

