  const success = Reflect.get(parsed, 'success');
  const message = Reflect.get(parsed, 'message');
  if (typeof success !== 'boolean' || typeof message !== 'string') {
    throw new Error('Database command result must contain boolean success and string message.');
  }
  return { success, message };
}

